          {
            "task_id": "STEP_003A",
            "name": "Verify server starts and binds port",
            "description": "Check that the FastAPI server starts successfully and binds to port 8000 without requiring manual shutdown",
            "target_files": ["backend/app.py"],
            "required_context": [],
            "dependencies": ["STEP_001B", "STEP_002A"],
            "acceptance_criteria": [
              "Server process starts within 30 seconds",
              "Port 8000 is listening for connections",
              "No interactive prompts or infinite startup loops"
            ],
            "test_commands": [
              "timeout 30 python backend/app.py",
              "timeout 5 bash -c 'until curl -s http://localhost:8000; do sleep 1; done'"
            ]
          }
        ]
      }
    ],
